export function initialize(dotNetRef, timeoutMs) {
    const state = {
        isIdle: false,
        timerId: null,
        dotNetRef,
        timeoutMs,
    };

    const events = ["mousemove", "keydown", "click", "scroll", "touchstart"];

    function resetTimer() {
        clearTimeout(state.timerId);
        if (state.isIdle) {
            state.isIdle = false;
            state.dotNetRef.invokeMethodAsync("OnActiveCallback");
        }
        state.timerId = setTimeout(() => {
            state.isIdle = true;
            state.dotNetRef.invokeMethodAsync("OnIdleCallback");
        }, state.timeoutMs);
    }

    function handler() {
        resetTimer();
    }

    events.forEach(e => document.addEventListener(e, handler, { passive: true }));
    resetTimer();

    return {
        dispose() {
            clearTimeout(state.timerId);
            events.forEach(e => document.removeEventListener(e, handler));
        },
    };
}

