    [Parameter] public EventCallback OnActive { get; set; }

    private IJSObjectReference? _module;
    private IJSObjectReference? _tracker;
    private DotNetObjectReference<UserActivityTracker>? _dotNetRef;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!firstRender) return;

        _dotNetRef = DotNetObjectReference.Create(this);
        _module = await JS.InvokeAsync<IJSObjectReference>(
            "import", "./js/userActivityTracker.js");
        _tracker = await _module.InvokeAsync<IJSObjectReference>(
            "initialize", _dotNetRef, TimeoutSeconds * 1000);
    }

    [JSInvokable]
    public async Task OnIdleCallback() => await OnIdle.InvokeAsync();

    [JSInvokable]
    public async Task OnActiveCallback() => await OnActive.InvokeAsync();

    public async ValueTask DisposeAsync()
    {
        if (_tracker is not null)
        {
            await _tracker.InvokeVoidAsync("dispose");
            await _tracker.DisposeAsync();
        }

        if (_module is not null)
        {
            await _module.DisposeAsync();
        }

        _dotNetRef?.Dispose();
    }
}

